function validate([grid]) {
  if (!Array.isArray(grid) || grid.length < 1 || grid.length > 1000) return 'grid needs 1 to 1000 rows.';
  const n = grid[0].length;
  if (n < 1 || n > 1000) return 'Each row needs 1 to 1000 cells.';
  if (grid.some(row => row.length !== n)) return 'All rows must have the same length.';
  if (grid.length * n > 100000) return 'grid can hold at most 10^5 cells.';
  if (grid.some(row => row.some(v => v !== 0 && v !== 1))) return 'Each cell is 0 or 1.';
  return null;
}

