function countPyramids(grid) {
  const m = grid.length;
  const n = grid[0].length;
  const down = Array.from({ length: m }, () => new Array(n).fill(0));
  const up = Array.from({ length: m }, () => new Array(n).fill(0));
  let total = 0;

  for (let r = m - 1; r >= 0; r--) {
    for (let c = 0; c < n; c++) {
      if (grid[r][c] === 0) {
        continue;
      }
      if (r === m - 1 || c === 0 || c === n - 1) {
        down[r][c] = 1;
      } else {
        down[r][c] = 1 + Math.min(down[r + 1][c - 1], down[r + 1][c], down[r + 1][c + 1]);
      }
      total += down[r][c] - 1;
    }
  }

  for (let r = 0; r < m; r++) {
    for (let c = 0; c < n; c++) {
      if (grid[r][c] === 0) {
        continue;
      }
      if (r === 0 || c === 0 || c === n - 1) {
        up[r][c] = 1;
      } else {
        up[r][c] = 1 + Math.min(up[r - 1][c - 1], up[r - 1][c], up[r - 1][c + 1]);
      }
      total += up[r][c] - 1;
    }
  }
  return total;
}

