function countPyramids(grid) {
  const m = grid.length, n = grid[0].length;
  const fertile = (i, j) => i >= 0 && i < m && j >= 0 && j < n && grid[i][j] === 1;
  let count = 0;
  for (let r = 0; r < m; r++) {
    for (let c = 0; c < n; c++) {
      for (let h = 2; h <= m; h++) {
        let pyramid = true, inverse = true;
        for (let k = 0; k < h; k++) {
          for (let j = c - k; j <= c + k; j++) {
            if (!fertile(r + k, j)) pyramid = false;
            if (!fertile(r - k, j)) inverse = false;
          }
        }
        if (pyramid) count++;
        if (inverse) count++;
      }
    }
  }
  return count;
}

