function generate(rand, size) {
  const densities = [0.5, 0.7, 0.85, 0.95, 1];
  const p = densities[Math.floor(rand() * densities.length)];
  let m, n;
  if (size === 'large') {
    m = 60 + Math.floor(rand() * 41);
    n = 60 + Math.floor(rand() * 41);
  } else {
    m = 1 + Math.floor(rand() * 6);
    n = 1 + Math.floor(rand() * 7);
  }
  const grid = Array.from({ length: m }, () => Array.from({ length: n }, () => (rand() < p ? 1 : 0)));
  return [grid];
}
